import { Page, Section, Callout, Button, Table, Input, Status, Divider, useState, useMemo, useEffect, useRef, useGrokTheme, type ReactNode } from "grok/canvas";

type SubRule = { id: string; nameHe: string };
type ReminderBlock = { title: string; body: string; examples: { ar: string; he: string }[]; pitfall?: string; recog?: string; steps?: string[]; contrast?: { ar: string; he: string }[]; traps?: string[]; srs?: string[] };
type MSlot = { opts: string[]; ans: number; note: string; bare: string };
type Q = {
  id: string; subRuleId: string; prompt: string; promptIsArabic: boolean; sentence?: string; hint?: string;
  options: string[]; answer: number; explain: string; optionNotes?: string[]; fullSentence: string; translation: string; target?: string; multi?: MSlot[];
};
type ReadQ = { id: string; prompt: string; options: string[]; answer: number; explain: string };
type ArSeg = { text: string; hi?: boolean };
type RSent = { ar: string; he: string; m?: string[][] };
type Reading = { title: string; paras: RSent[][]; gloss: string[][] };
type CSent = { v: string; he: string; m?: string[][] };
type ContPassage = { title: string; intro: string; sents: CSent[]; gloss: string[][] };
type RTable = { title: string; columns: string[]; rows: string[][] };
type TopicData = {
  id: string; num: number; titleHe: string; ready: boolean; lastPracticed: string; updated?: string;
  reminder: string[]; reminderBlocks?: ReminderBlock[]; subRules: SubRule[]; gloss?: string[][];
  questions: Q[]; readingAr?: ArSeg[]; readingHe?: string; reading?: Reading; readingQs: ReadQ[];
  parts?: { prefix: string; n: number }[]; tables?: RTable[]; cont?: ContPassage[];
  levels?: { label: string; prefix: string; n: number }[]; contMode?: string; brief?: ReminderBlock[]; link?: { id: string; label: string };
};
type Phase = "home" | "reminder" | "quiz" | "reading" | "summary";
type RowInfo = { num: number; title: string; status: string; last: string; upd: string; ready: boolean; id: string };

function shuffle<T>(arr: T[]): T[] {
  const a: T[] = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j: number = Math.floor(Math.random() * (i + 1));
    const tmp: T = a[i]; a[i] = a[j]; a[j] = tmp;
  }
  return a;
}
// Every round reshuffles the options of every question; the correct answer follows its option (index is recomputed), never a fixed position.
function shuffleQ(q: Q): Q {
  if (q.multi) return { ...q, multi: q.multi.map((sl: MSlot) => { const pr: number[] = shuffle(sl.opts.map((_: string, i: number) => i)); return { ...sl, opts: pr.map((i: number) => sl.opts[i]), ans: pr.indexOf(sl.ans) }; }) };
  const perm: number[] = shuffle(q.options.map((_: string, i: number) => i));
  const notes: string[] | undefined = q.optionNotes;
  return { ...q, options: perm.map((i: number) => q.options[i]), optionNotes: notes ? perm.map((i: number) => notes[i] ?? "") : undefined, answer: perm.indexOf(q.answer) };
}
function shuffleRQ(q: ReadQ): ReadQ {
  const perm: number[] = shuffle(q.options.map((_: string, i: number) => i));
  return { ...q, options: perm.map((i: number) => q.options[i]), answer: perm.indexOf(q.answer) };
}
function pickQuestions(bank: Q[], n: number): Q[] { return shuffle(bank).slice(0, Math.min(n, bank.length)).map(shuffleQ); }
function mq(id: string, sr: string, prompt: string, options: string[], answer: number, explain: string, notes: string[], translation: string, full?: string): Q {
  const isAr: boolean = !/[\u0590-\u05FF]/.test(prompt);
  const fs: string = full ?? (prompt.indexOf("___") >= 0 ? prompt.replace("___", options[answer]) : prompt);
  return { id: id, subRuleId: sr, prompt: prompt, promptIsArabic: isAr, options: options, answer: answer, explain: explain, optionNotes: notes, fullSentence: fs, translation: translation };
}
function rq(id: string, prompt: string, options: string[], answer: number, explain: string): ReadQ {
  return { id: id, prompt: prompt, options: options, answer: answer, explain: explain };
}
function rs(ar: string, he: string, m?: string[][]): RSent { return { ar: ar, he: he, m: m }; }
// Reading practice helpers: unvowelled text is derived from the vowelled source, so prompts can never leak harakat.
const HARAKAT_RE: RegExp = /[\u064B-\u0652\u0670]/g;
function noVowels(s: string): string { return s.replace(HARAKAT_RE, ""); }
function noEnding(w: string): string {
  const mm: RegExpMatchArray | null = w.match(/^([\s\S]*?)([^\u0621-\u0652\u0670]*)$/);
  let core: string = mm ? mm[1] : w;
  const tail: string = mm ? mm[2] : "";
  if (/(\u064B\u0627|\u0627\u064B)$/.test(core)) core = core.slice(0, core.length - 2);
  const mk: RegExpMatchArray | null = core.match(/[\u064B-\u0652]+$/);
  if (mk) core = core.slice(0, core.length - mk[0].length) + (mk[0].indexOf("\u0651") >= 0 ? "\u0651" : "");
  return core + tail;
}
function noEndings(s: string): string { return s.split(" ").map(noEnding).join(" "); }
function pa(id: string, sr: string, full: string, options: string[], answer: number, explain: string, notes: string[], translation: string): Q {
  const q: Q = mq(id, sr, noVowels(full), options, answer, explain, notes, translation, full);
  return { ...q, promptIsArabic: true, hint: "חלק א׳ · בלי ניקוד: איך הוגים את המילה המסומנת?", target: noVowels(options[answer]) };
}
function pb(id: string, sr: string, full: string, options: string[], answer: number, explain: string, notes: string[], translation: string, bare?: string): Q {
  const shown: string = bare ?? noEnding(options[answer]);
  const q: Q = mq(id, sr, noEndings(full.replace(options[answer], shown)), options, answer, explain, notes, translation, full);
  return { ...q, promptIsArabic: true, hint: "חלק ב׳ · ניקוד סופי: מה הסיומת של המילה המסומנת?", target: noEnding(shown) };
}
function cs(v: string, he: string, m?: string[][]): CSent { return { v: v, he: he, m: m }; }
// Multi-ending question: each slot is [option1, option2, option3, optional bare form]; the prompt strips the endings of the whole sentence.
function pm(id: string, sr: string, full: string, slots: string[][], ans: number[], snotes: string[], explain: string, translation: string): Q {
  let shown: string = full;
  const ms: MSlot[] = slots.map((sl: string[], i: number) => {
    const opts: string[] = sl.slice(0, 3);
    const bare: string = sl[3] ? sl[3] : noEnding(opts[ans[i]]);
    shown = shown.replace(opts[ans[i]], bare);
    return { opts: opts, ans: ans[i], note: snotes[i] ?? "", bare: noEnding(bare) };
  });
  return { id: id, subRuleId: sr, prompt: noEndings(shown), promptIsArabic: true, hint: "נקדו את כל הסיומות המסומנות", options: ["✓"], answer: 0, explain: explain, fullSentence: full, translation: translation, multi: ms };
}
// Expanded explanation per question id, shown under the short explanation.
const MORE: Record<string, string> = {
  nqa1: "1. מה התפקיד: אחרי המילה המודגשת בא الطَّالِبُ — והוא מי שעשה את הכתיבה. לכן המילה היא פועל פעיל בעבר, והתלמיד הוא ה־فَاعِل שלו.\n2. למה كَتَبَ: פועל פעיל בבניין 1 בנוי במשקל فَعَلَ — שלוש פתחות. כשיש עושה ברור במשפט, ברירת המחדל היא פעיל.\n3. למה לא كُتِبَ: זו צורת הסביל (נכתב). בסביל העושה לא מוזכר, ופה הוא מוזכר מיד אחרי הפועל — סתירה.\n4. למה לא كُتُبُ: זה שם ברבים (ספרים). שם לא יכול לקבל אחריו فَاعِل ומושא (الْوَاجِبَ) כמו פועל.\n5. כלל אצבע: פועל + שם ברפע שיכול לעשות את הפעולה ⇐ פעיל. ← לחזרה: הכלל ״פעיל או סביל״ בנושא הזה.",
  nqa2: "1. מה התפקיד: הכינוי ـهَا בתוך لٰكِنَّهَا מצביע על الرِّسَالَة (המכתב). המילה המודגשת מספרת מה קרה למכתב.\n2. למה كُتِبَتْ: מכתב לא כותב — הוא הדבר שנכתב. לכן סביל במשקל فُعِلَ: ضمة על האות הראשונה וכסרה לפני האחרונה, ו־ـَتْ בגלל שהמכתב נקבה.\n3. למה לא كَتَبَتْ: זה ״היא כתבה״ — פעיל. זה היה אומר שהמכתב כתב משהו.\n4. למה לא كَتَبْتُ: זה ״אני כתבתי״ — אבל תחילת המשפט אומרת שאף אחד לא יודע מי כתב, אז הדובר לא מספר שהוא כתב.\n5. רמז בטקסט: ״אף אחד לא יודע מי״ + אין עושה במשפט ⇐ כמעט תמיד סביל. ← לחזרה: נושא 20 (סביל).",
  nqa3: "1. מה התפקיד: המילה באה אחרי ثَلَاثَة — מספר. אחרי 3 עד 10 בא ה־مَعْدُود: שם ברבים ובג׳ר (סמיכות).\n2. למה كُتُبٍ: זה הרבים השבור של كِتَاب במשקל فُعُل (ضمة–ضمة). הכסרה עם תנוין בסוף כי הוא מג׳רור ואין לו ال. גם התואר جَدِيدَةٍ בג׳ר ובנקבה — כמו שמתאים לרבים של לא־אנושי.\n3. למה לא كَتَبَ ו־كُتِبَ: אלה פעלים (כתב / נכתב). אחרי מספר לא בא פועל, ופועל לא מקבל תואר כמו جَدِيدَة.\n4. כלל אצבע: מספר, מילת יחס או ال לפני המילה ⇐ זה שם, לא פועל. ← לחזרה: נושא 21 (מספרים) ונושא 14 (רבים).",
  nqa4: "1. מה התפקיד: אחרי הפועל בא سَيَّارَتِي (המכונית שלי), ואין במשפט שום גנב.\n2. למה سُرِقَتْ: מכונית לא גונבת — היא נגנבה. לכן סביל במשקל فُعِلَتْ, והמכונית היא نَائِب فَاعِل (ממלאת את מקום העושה) ולכן ברפע.\n3. למה לא سَرَقَتْ: ״היא גנבה״ — זה היה עושה מהמכונית גנבת.\n4. למה לא سَرَقْتُ: ״אני גנבתי״ — ואז הדובר היה הגנב של המכונית של עצמו. המשפט מתאר תלונה על גניבה, לא הודאה.\n5. כלל אצבע: אם הדבר שאחרי הפועל לא יכול לבצע את הפעולה ואין עושה אחר ⇐ סביל. ← לחזרה: נושא 20 (סביל).",
  nqa5: "1. מה התפקיד: הפועל פותח את המשפט, ואחריו الْأُسْتَاذُ (העושה) ושני מושאים: الطُّلَّابَ וגם قَوَاعِدَ.\n2. למה عَلَّمَ: שני מושאים הם סימן מובהק לבניין 2 הגורם — ״גרם למישהו לדעת״ = לימד. בבניין 2 יש שדה על האות האמצעית: فَعَّلَ.\n3. למה לא عَلِمَ: בניין 1 = ידע. אפשר ״ידע משהו״, אבל המרצה לא ״ידע את הסטודנטים את הכללים״.\n4. למה לא عُلِمَ: סביל (נודע). בסביל אין עושה ברפע אחרי הפועל, ופה יש.\n5. כלל אצבע: פועל עם שני מושאים, או משמעות של ״לגרום ל־״ ⇐ חשבו על בניין 2 או 4. ← לחזרה: הכלל ״בניינים״ בנושא הזה.",
  nqa6: "1. מה התפקיד: الطَّالِبُ הוא העושה, ו־مَشْرُوعَهُ (הפרויקט שלו) הוא מושא בנצב.\n2. למה قَدَّمَ: בניין 2 (فَعَّلَ) = הציג, הגיש — פועל יוצא שמקבל מושא. ״הציג את הפרויקט מול הכיתה״ — מתאים בדיוק.\n3. למה לא قَدِمَ: בניין 1 = הגיע. ״הגיע את הפרויקט״ — לא אפשרי, כי قَدِمَ לא מקבל מושא ישיר.\n4. למה לא قُدِّمَ: סביל של בניין 2 (הוגש). אבל יש עושה מפורש (الطَّالِبُ) — בסביל הוא לא היה מופיע.\n5. כלל אצבע: יש מושא ישיר? בדקו איזה בניין של השורש יוצא. ← לחזרה: הכלל ״בניינים״ בנושא הזה.",
  nqa7: "1. מה התפקיד: המילה פותחת את המשפט (مُبْتَدَأ) ואחריה يَشْرَحُ — היא מי שמסביר.\n2. למה الْمُعَلِّمُ: מי שעושה את הפעולה = اسْم فَاعِل. בבניין 2 הוא במשקל مُفَعِّل: ضمة על המ׳, שדה על האמצעית, וכסרה לפני האות האחרונה.\n3. למה לא الْمُعَلَّمُ: זה اسْم مَفْعُول (מי שמלמדים אותו — פתחה לפני האחרונה). מי שמסביר את השיעור הוא המורה, לא התלמיד.\n4. למה לא الْمَعْلَمُ: זה מקום או ציון דרך (معلم = landmark), במשקל مَفْعَل — ציון דרך לא מסביר שיעור.\n5. כלל אצבע לבניינים 2–10: כסרה לפני האחרונה = עושה; פתחה לפני האחרונה = מושא. ← לחזרה: הכלל ״اسم فاعل / اسم مفعول״.",
  nqa8: "1. מה התפקיד: המילה היא תואר (نَعْت) של الرِّسَالَةُ — ולכן גם היא ברפע ועם ال.\n2. למה الْمُرْسَلَةُ: המכתב נשלח — הוא לא שולח. לכן اسْم مَفْعُول של בניין 4 (أَرْسَلَ): مُفْعَل — ضمة על המ׳, סכון על הר׳ ופתחה לפני האחרונה.\n3. למה לא الْمُرْسِلَةُ: עם כסרה זו השולחת — اسْم فَاعِل. מכתב לא שולח.\n4. למה לא الْمَرْسَلَةُ: בבניין 4 התחילית היא תמיד مُـ עם ضمة. مَـ עם פתחה שייך לבניין 1 או לשמות מקום.\n5. כלל אצבע: כל השמות הנגזרים מבניינים 2–10 מתחילים ב־مُـ. ← לחזרה: הכלל ״اسم فاعل / اسم مفعول״.",
  nqa9: "1. מה התפקיד: המילה היא ח׳בר של الْبَرْنَامَجُ (התוכנה) — היא מתארת את מצבה.\n2. למה مُسْتَخْدَمٌ: משתמשים בתוכנה — היא לא משתמשת. לכן اسْم مَفْعُول של בניין 10: مُسْتَفْعَل, פתחה לפני האחרונה.\n3. למה לא مُسْتَخْدِمٌ: עם כסרה זה ״משתמש״ (user) — אדם שמשתמש. תוכנה לא משתמשת בבתי ספר.\n4. למה לא مَسْتَخْدَمٌ: בבניין 10 התחילית היא תמיד مُـ עם ضمة.\n5. כלל אצבע: שאלו ״מי עושה למי?״ — אם המילה מתארת את מי שהפעולה נעשית עליו ⇐ פתחה לפני האחרונה. ← לחזרה: הכלל ״اسم فاعل / اسم مفعول״.",
  nqa10: "1. מה התפקיד: יש פועל (يُحِبُّ) ועושה (أَخِي). המילה היא המושא — מה הוא אוהב — והיא נסמכת ל־اللُّغَاتِ.\n2. למה تَعَلُّمَ: מושא שהוא גם נסמך חייב להיות שם. השם של ״ללמוד״ בבניין 5 הוא המצדר تَفَعُّل: تَعَلُّم. בנצב כי הוא מושא, בלי תנוין כי הוא נסמך.\n3. למה לא تَعْلَمُ: ״את יודעת / הוא יודע״ — פועל בעתיד. פועל לא יכול להיות נסמך לשם.\n4. למה לא تَعَلَّمَ: ״למד״ — פועל בעבר. אחרי يُحِبُّ + עושה לא בא עוד פועל בעבר בלי أَنْ.\n5. כלל אצבע: מילה שאחריה בא שם מיודע בג׳ר בלי מילת יחס ⇐ היא כנראה שם בסמיכות (לעתים מצדר). ← לחזרה: הכלל ״מצדרים״ ונושא 17 (إضافة).",
  nqa11: "1. מה התפקיד: המילה פותחת את המשפט, נסמכת ל־الْقَوَاعِدِ, והפועל של המשפט הוא يُسَاعِدُ.\n2. למה فَهْمُ: היא נושא המשפט (מה עוזר? ההבנה) — לכן שם: המצדר فَهْم (משקל فَعْل), مُبْتَدَأ ברפע, בלי תנוין כי הוא נסמך.\n3. למה לא فَهِمَ: ״הוא הבין״ — פועל. אז היו במשפט שני פעלים בלי קשר, ו־الْقَوَاعِدِ היה צריך להיות מושא בנצב ולא בג׳ר.\n4. למה לא فُهِمَ: סביל (הובן) — אותה בעיה: הכללים היו צריכים להיות ברפע כ־نَائِب فَاعِل.\n5. כלל אצבע: הסיומת של המילה שאחרי (ג׳ר / נצב / רפע) מסגירה אם לפניה שם או פועל. ← לחזרה: הכלל ״מצדרים״.",
  nqa12: "1. מה התפקיד: המילה היא המבתדא ונסמכת ל־الْمَدِينَةِ; הח׳בר הוא ضَيِّقَةٌ وَمُزْدَحِمَةٌ.\n2. למה طُرُقُ: הח׳בר בנקבה יחיד — ככה מתאימים לרבים של דברים (לא בני אדם). לכן זה רבים: طُرُق, במשקל فُعُل, של طَرِيق.\n3. למה לא طَرَقَ: ״דפק״ — פועל. פועל לא נסמך לשם ולא מקבל ח׳בר.\n4. למה לא طُرِقَ: ״נדפק״ — סביל, אותה בעיה.\n5. כלל אצבע: תואר בנקבה יחיד אחרי שם לא־אנושי ⇐ חשדו שהשם ברבים שבור. ← לחזרה: הכלל ״רבים שבורים״ ונושא 14.",
  nqa13: "1. מה התפקיד: המילה היא ה־مَعْدُود אחרי ثَلَاثَ — ברבים ובג׳ר.\n2. למה جُمَلٍ: במספרים 3–10 המספר הפוך במין: ثَلَاث בלי ة ⇐ היחיד הוא נקבה. جُمْلَة (משפט) נקבה, והרבים שלה جُمَل (משקל فُعَل). וגם ההקשר מתאים: לכתוב משפטים.\n3. למה לא جَمَلٍ: גמל — שם זכר, ואז היה צריך ثَلَاثَة עם ة. וגם ״כתוב שלושה גמלים״ לא הגיוני.\n4. למה לא جَمَّلَ: ״ייפה״ — פועל בבניין 2. אחרי מספר לא בא פועל.\n5. כלל אצבע: במספרים 3–10, בדקו את ה־ة של המספר — היא מגלה את מין היחיד. ← לחזרה: נושא 21 (מספרים).",
  nqa14: "1. מה התפקיד: המילה היא המושא של رَفَعَ (הרים, הניף) ונסמכת ל־بِلَادِهِ — לכן היא שם בנצב.\n2. למה عَلَمَ: מה מניפים אחרי ניצחון? דגל — عَلَم (שתי פתחות). בנצב בלי תנוין כי הוא נסמך.\n3. למה לא عِلْمَ: ידע / מדע. ״הניף את מדע ארצו״ לא הגיוני.\n4. למה לא عَلِمَ: ״ידע״ — פועל, לא יכול להיות מושא ולא נסמך.\n5. כלל אצבע: באותו שלד ע־ל־מ יש כמה מילים — רק ההקשר (פועל, נושא, עולם תוכן) מכריע. ← לחזרה: הכלל ״מילים שנכתבות אותו דבר״.",
  nqa15: "1. מה התפקיד: המילה באה אחרי מילת היחס مِنْ, ובמשפט על טבעת.\n2. למה ذَهَبٍ: אחרי מילת יחס תמיד בא שם בג׳ר. ״טבעת מזהב״ ⇐ ذَهَب = זהב, עם תנוין כסרה כי אין ال.\n3. למה לא ذَهَبَ: ״הלך״ — פועל. מילת יחס לא באה לפני פועל.\n4. למה לא ذُهِبَ: צורת סביל — גם היא פועל, ובכלל לא בשימוש כזה.\n5. כלל אצבע: مِنْ / فِي / إِلَى / عَلَى / بِـ לפני מילה ⇐ שם בג׳ר. ← לחזרה: הכלל ״מילים שנכתבות אותו דבר״ ונושא 13.",
  nqa16: "1. מה התפקיד: המילה היא השם של كَانَ (ברפע), ואחריה يَسْكُنُ — מי שגר בארמון.\n2. למה الْمَلِكُ: מי שגר בארמון הוא אדם — מלך: مَلِك במשקל فَعِل (פתחה, כסרה).\n3. למה לא الْمُلْكُ: מלוכה / שלטון — מושג, לא אדם. מלוכה לא ״גרה״.\n4. למה לא الْمَلَكُ: מלאך. מלאך שגר בארמון גדול לא מתאים להקשר.\n5. כלל אצבע: שאלו מי יכול לבצע את הפעולה שאחרי — זה מכריע בין מילים בעלות אותו שלד. ← לחזרה: הכלל ״מילים שנכתבות אותו דבר״.",
  nqb1: "1. מה התפקיד: משפט שמני — الْجَوُّ פותח אותו (مُبْتَدَأ), והמילה המודגשת אומרת מה מצבו: היא ה־خَبَر.\n2. למה جَمِيلٌ: גם המבתדא וגם הח׳בר ברפע. לח׳בר אין ال ואין סמיכות ⇐ הוא מקבל תנוין ضمة: ـٌ (נהגה ג׳מילון).\n3. למה לא جَمِيلًا: תנוין פתחה = נצב. ח׳בר עובר לנצב רק אחרי كَانَ ואחיותיה — וכאן אין كَانَ.\n4. למה לא جَمِيلٍ: תנוין כסרה = ג׳ר. אין כאן מילת יחס ואין סמיכות שתגרור אותו.\n5. איך לזהות מהר: משפט שמתחיל בשם עם ال, ואחריו שם בלי ال ⇐ מבתדא + ח׳בר, שניהם ـُ / ـٌ. ← לחזרה: נושא 7 (مبتدأ وخبر).",
  nqb2: "1. מה התפקיד: המשפט פותח בפועל حَضَرَ (הגיע). מי הגיע? המנהל — הוא ה־فَاعِل.\n2. למה الْمُدِيرُ: הפאעל תמיד ברפע. יש לו ال, ולכן אין תנוין — רק ضمة אחת: ـُ.\n3. למה לא الْمُدِيرَ: פתחה = נצב, מתאים למושא (מי שהפעולה נעשית עליו). המנהל לא ״הוגע״ — הוא הגיע בעצמו.\n4. למה לא الْمُدِيرِ: כסרה = ג׳ר, מגיעה אחרי מילת יחס או בסמיכות. אין כאן כזה לפני המילה (إِلَى באה רק אחריה, לפני الِاجْتِمَاعِ).\n5. שימו לב: مُتَأَخِّرًا בסוף הוא حَال בנצב — הוא לא משנה את הרפע של הפאעל. ← לחזרה: נושא 13 (יחסות).",
  nqb3: "1. מה התפקיד: قَرَأَتْ = היא קראה. מי קראה? سَلْمَى — הפאעל. מה קראה? הסיפור — זה ה־مَفْعُول بِه.\n2. למה الْقِصَّةَ: המושא הישיר תמיד בנצב. עם ال אין תנוין ⇐ פתחה אחת: ـَ.\n3. למה לא الْقِصَّةُ: ضمة = רפע, כאילו הסיפור הוא שקרא. אבל ـَتْ בפועל ו־سَلْمَى אחריו מראים שסלמא היא הקוראת.\n4. למה לא الْقِصَّةِ: כסרה = ג׳ר — אין מילת יחס לפני המילה.\n5. מלכודת: ב־سَلْمَى (שנגמר ב־ى) אי אפשר לראות את הרפע — זה שם מקצור. לכן מזהים לפי ההיגיון ולפי ה־ـَتْ של הפועל. ← לחזרה: נושא 13 (יחסות).",
  nqb4: "1. מה התפקיד: המילה באה מיד אחרי מילת היחס إِلَى — היא اسْم مَجْرُور.\n2. למה مَدِينَةٍ: כל שם אחרי מילת יחס בג׳ר. אין ال ואין סמיכות ⇐ תנוין כסרה: ـٍ (מדינתין). גם התואר قَدِيمَةٍ מקבל אותו סימן, כי תואר מתאים לשם שלו.\n3. למה לא مَدِينَةٌ: תנוין ضمة = רפע (מבתדא, ח׳בר, פאעל). מילת יחס לא משאירה שם ברפע.\n4. למה לא مَدِينَةً: תנוין פתחה = נצב (מושא, حَال וכו׳). ושימו לב: אחרי ة אין מוסיפים אלף גם בנצב.\n5. כלל ברזל: מילת יחס ⇐ כסרה (או תנוין כסרה). ← לחזרה: נושא 13 (יחסות).",
  nqb5: "1. מה התפקיד: بَاب פותח משפט שמני (המבתדא), והוא הנסמך בצירוף بَابُ الْبَيْتِ (הדלת של הבית). הח׳בר: مَفْتُوحٌ.\n2. למה بَابُ: המבתדא ברפע ⇐ ضمة. הוא נסמך (مُضَاف), ונסמך לעולם לא מקבל ال ולא תנוין ⇐ ضمة אחת בלבד.\n3. למה לא بَابٌ: עם תנוין הוא היה מנותק מהמילה הבאה — ״דלת. הבית...״. בסמיכות אסור תנוין על הנסמך.\n4. למה לא بَابِ: כסרה = ג׳ר. הג׳ר שייך למילה השנייה בסמיכות (الْبَيْتِ — مُضَاف إِلَيْهِ), לא לראשונה.\n5. כלל אצבע לסמיכות: הסיומת של הנסמך נקבעת לפי תפקידו במשפט (כאן רפע), והנסמך אליו תמיד בג׳ר. ← לחזרה: נושא 17 (إضافة).",
  nqb6: "1. מה התפקיד: إِنَّ פותחת משפט שמני. השם שבא אחריה הוא اسْم إِنَّ, והח׳בר הוא نُورٌ.\n2. למה الْعِلْمَ: إِنَّ ואחיותיה (أَنَّ, لٰكِنَّ, كَأَنَّ, لَيْتَ, لَعَلَّ) מעבירות את השם שאחריהן לנצב ⇐ פתחה. עם ال אין תנוין.\n3. למה לא الْعِلْمُ: בלי إِنَّ זה היה נכון (מבתדא ברפע). إِنَّ משנה רק את השם הראשון.\n4. למה לא الْعِلْمِ: כסרה = ג׳ר. إِنَّ היא לא מילת יחס.\n5. מלכודת: הח׳בר (نُورٌ) נשאר ברפע — לא כל מה שאחרי إِنَّ בנצב. ← לחזרה: נושא 5 (إِنَّ وأخواتها).",
  nqb7: "1. מה התפקיד: كَانَ פותחת משפט שמני בעבר. الطَّقْسُ = השם שלה; המילה המודגשת = הח׳בר שלה (מה היה מזג האוויר).\n2. למה بَارِدًا: كَانَ עושה ההפך מ־إِنَّ: השם נשאר ברפע, והח׳בר עובר לנצב. אין ال ⇐ תנוין פתחה, נכתב עם אלף: ـًا.\n3. למה לא بَارِدٌ: בלי كَانَ (الطَّقْسُ بَارِدٌ) זה היה רפע. كَانَ מעבירה את הח׳בר לנצב.\n4. למה לא بَارِدٍ: כסרה = ג׳ר — אין מילת יחס ואין סמיכות.\n5. דרך לזכור: إِنَّ ⇐ השם בנצב; كَانَ ⇐ הח׳בר בנצב. אחיות كَانَ: صَارَ, أَصْبَحَ, لَيْسَ, مَا زَالَ, أَمْسَى, ظَلَّ. ← לחזרה: נושא 6 (كَانَ وأخواتها).",
  nqb8: "1. מה התפקיד: أَشْرَب הוא פועל בעתיד (مُضَارِع) שבא אחרי أَنْ — ״ש־״ / ״ל־״ (לשתות).\n2. למה أَشْرَبَ: أَنْ, لَنْ, كَيْ, لِـ, حَتَّى מעבירות את המצארע לנצב ⇐ פתחה בסוף.\n3. למה לא أَشْرَبُ: ضمة = מרפוע, הצורה הרגילה של העתיד כשאין לפניו מילה משנה. כאן יש أَنْ.\n4. למה לא أَشْرَبْ: סכון = מג׳זום — אחרי لَمْ, لَا של איסור, ל־لِـ של ציווי או إِنْ של תנאי.\n5. כלל אצבע: أَنْ לפני פועל ⇐ פתחה; لَمْ לפני פועל ⇐ סכון. ← לחזרה: נושא 1 (أَنْ ו־لَنْ).",
  nqb9: "1. מה התפקיד: يَحْضُر הוא פועל בעתיד, ולפניו لَمْ — שלילת עבר (לא הגיע).\n2. למה يَحْضُرْ: لَمْ מג׳זמת את המצארע ⇐ הסיומת נעלמת לסכון.\n3. למה לא يَحْضُرُ: ضمة = מרפוע — הצורה הרגילה (״לא מגיע״ עם لَا). עם لَمْ אסור.\n4. למה לא يَحْضُرَ: פתחה = מנצוב, מגיע אחרי أَنْ / لَنْ — לא אחרי لَمْ.\n5. מלכודת: אחרי لَمْ הפועל בצורת עתיד אבל המשמעות עבר. בפועל חלש הסכון מפיל אות: لَمْ يَقُلْ, لَمْ يَمْشِ, لَمْ يَدْعُ. ← לחזרה: נושא 2 (لَمْ ו־מג׳זום).",
  nqb10: "1. מה התפקיד: يَمْشِي הוא פועל בעתיד ששורשו נגמר ב־ي (פועל חסר), ולפניו لَنْ — שלילת עתיד.\n2. למה يَمْشِيَ: لَنْ מנצבת ⇐ פתחה. בפועל שנגמר ב־ي הפתחה נראית ונשמעת: يَمْشِيَ.\n3. למה לא يَمْشِي: זו צורת הרפע — ב־ي הסופית לא רואים ضمة (היא ״מוערכת״). זה נכון בלי لَنْ.\n4. למה לא يَمْشِ: נפילת ה־ي היא צורת הג׳זם — אחרי لَمْ (لَمْ يَمْشِ), לא אחרי لَنْ.\n5. טבלה קטנה: يَمْشِي ⇐ رفع يَمْشِي / نصب يَمْشِيَ / جزم يَمْشِ. ב־ى (يَنْسَى) הנצב לא נראה בכלל, והג׳זם מפיל את האלף: لَمْ يَنْسَ. ← לחזרה: נושא 10 (פעלים חריגים).",
  nqb11: "1. מה התפקיד: نَجَحَ = הצליח. מי הצליח? שני התלמידים — הפאעל, בזוגי.\n2. למה الطَّالِبَانِ: בזוגי הרפע מסומן בסיומת ـَانِ (אלף + נון עם כסרה), לא ב־ضمة.\n3. למה לא الطَّالِبَيْنِ: ـَيْنِ היא סיומת הזוגי בנצב ובג׳ר — למושא או אחרי מילת יחס.\n4. למה לא الطَّالِبَا: נפילת הנון קורית רק כשהזוגי נסמך (طَالِبَا الْمَدْرَسَةِ). כאן הוא לא נסמך.\n5. מלכודת: הפועל נשאר ביחיד (نَجَحَ) כשהוא בא לפני הפאעל — גם אם הפאעל זוגי או רבים. ← לחזרה: נושא 15 (זוגי).",
  nqb12: "1. מה התפקיד: شَكَرَ = הודה. הפאעל: الْمُدِيرُ. למי הודה? למהנדסים — المَفْعُول بِه, ברבים שלמים זכר.\n2. למה الْمُهَنْدِسِينَ: ברבים שלמים זכר הנצב והג׳ר מסומנים ב־ـِينَ.\n3. למה לא الْمُهَنْدِسُونَ: ـُونَ = רפע (פאעל, מבתדא, ח׳בר). המהנדסים לא הודו — הודו להם.\n4. למה לא الْمُهَنْدِسُو: הנון נופלת רק כשהרבים נסמך (مُهَنْدِسُو الشَّرِكَةِ), ובכל מקרה ـُو היא צורת רפע.\n5. כלל: ـُونَ = רפע; ـِينَ = נצב וג׳ר. ← לחזרה: נושא 14 (רבים).",
  nqb13: "1. מה התפקיד: رَأَيْتُ = ראיתי (הפאעל הוא ـتُ). את מי ראיתי? את התלמידות — מושא בנצב, ברבות שלמות.\n2. למה الطَّالِبَاتِ: זה החריג הגדול: ברבות שלמות (ـَات) הנצב מסומן בכסרה, בדיוק כמו הג׳ר. בלי ال היה תנוין כסרה: طَالِبَاتٍ.\n3. למה לא الطَّالِبَاتُ: ضمة = רפע. התלמידות לא ראו — הן נראו.\n4. למה לא الطَّالِبَاتَ: הטעות הכי נפוצה! הנצב הרגיל הוא פתחה, אבל ב־ـَات אסור לשים פתחה.\n5. איך לזכור: ـَات יש רק שני מצבים — ـُ ברפע, ـِ בכל השאר. ← לחזרה: נושא 14 (רבים).",
  nqb14: "1. מה התפקיד: פועל בעתיד בגוף ״אתם״ אחרי أَنْ (צריך ש־ / ללמוד).\n2. למה تَدْرُسُوا: تَدْرُسُونَ הוא אחד מ״חמשת הפעלים״ (ـَانِ, ـُونَ, ـِينَ). בהם הנצב והג׳זם מסומנים בנפילת הנון. כותבים אלף בסוף שלא נהגית.\n3. למה לא تَدْرُسُونَ: זו צורת הרפע — עם הנון. אחרי أَنْ היא לא אפשרית.\n4. למה לא تَدْرُسْ: זה גוף ״אתה״ במג׳זום — גם הגוף לא מתאים (جَيِّدًا... قَبْلَ الِامْتِحَانِ נאמר לקבוצה), וגם אחרי أَنْ באה פתחה, לא סכון.\n5. כלל: בחמשת הפעלים — נון קיימת = רפע; נון נופלת = נצב או ג׳זם. ← לחזרה: נושא 1 (أَنْ ו־لَنْ).",
  nqb15: "1. מה התפקיד: המילה באה אחרי מילת היחס فِي ⇐ ג׳ר. היא רבים שבור של مَدْرَسَة.\n2. למה مَدَارِسَ: משקל مَفَاعِل (וגם مَفَاعِيل) הוא ممنوع من الصرف: לא מקבל תנוין, ובג׳ר בלי ال מקבל פתחה במקום כסרה.\n3. למה לא مَدَارِسٍ: תנוין אסור במילה ממנועה.\n4. למה לא مَدَارِسِ: כסרה רגילה חוזרת רק כשיש ال או סמיכות: فِي الْمَدَارِسِ, فِي مَدَارِسِ الْمَدِينَةِ. כאן אין.\n5. שימו לב: התואר كَثِيرَةٍ אינו ממנוע, ולכן מקבל ג׳ר רגיל עם תנוין. ← לחזרה: נושא 14 (רבים).",
  nqb16: "1. מה התפקיד: המשפט שלם בלי המילה (הילד חזר הביתה). המילה מוסיפה באיזה מצב הוא חזר — זה حَال.\n2. למה سَعِيدًا: الحال תמיד בנצב, בדרך כלל בלי ال ⇐ תנוין פתחה עם אלף: ـًا.\n3. למה לא سَعِيدٌ: רפע היה הופך אותה לח׳בר או תואר — אבל אין מבתדא שהיא מתארת, והיא לא תואר של الْبَيْتِ.\n4. למה לא سَعِيدٍ: ג׳ר היה הופך אותה לתואר של الْبَيْتِ (בית שמח) — לא המשמעות. היא מתארת את הילד.\n5. איך מזהים حَال: שאלו ״איך? / באיזה מצב?״ על העושה. ← לחזרה: נושא 25 (التمييز والحال).",
  nqb17: "1. מה התפקיד: המילה היא ה־مَعْدُود (מה שנספר) אחרי عِشْرِينَ — היא تَمْيِيز.\n2. למה كِتَابًا: אחרי 11–99 המעדוד ביחיד ובנצב עם תנוין: كِتَابًا.\n3. למה לא كِتَابٌ: רפע — אין לו תפקיד של מבתדא או פאעל.\n4. למה לא كِتَابٍ: ג׳ר ביחיד מגיע אחרי 100 ו־1000 (مِائَةُ كِتَابٍ, أَلْفُ كِتَابٍ). אחרי 3–10 בא ג׳ר ברבים (ثَلَاثَةُ كُتُبٍ).\n5. סיכום מספרים: 3–10 ⇐ רבים בג׳ר; 11–99 ⇐ יחיד בנצב; 100, 1000 ⇐ יחיד בג׳ר. ← לחזרה: נושא 21 (מספרים ומעדוד).",
};
// Detailed rule blocks for topics 26 and 27 (accordion; srs lists the sub-rules each block explains).
const READ_BLOCKS: ReminderBlock[] = [
  { title: "1) אסטרטגיה: איך קוראים משפט בלי ניקוד", srs: ["nq-context"],
    body: "טקסט ערבי רגיל (עיתון, ספר, שלט) נכתב כמעט תמיד בלי ניקוד. הקורא צריך להשלים בעצמו שני סוגים של תנועות: (1) התנועות שבתוך המילה — הן נקבעות לפי השורש, המשקל והמשמעות; (2) התנועה האחרונה (הסיומת, إِعْرَاب) — היא נקבעת לפי התפקיד של המילה במשפט.\nהטעות הנפוצה היא לקרוא מילה לפי הקריאה הראשונה שעולה בראש, בלי לבדוק אם היא מתאימה לשאר המשפט. לכן קוראים תמיד את כל המשפט לפני שמחליטים על הניקוד של מילה אחת.",
    recog: "סימנים שעוזרים גם בלי ניקוד: אותיות נוספות שמסמנות משקל (مُـ בתחילת שם, ا אחרי האות הראשונה, تَـ / اِسْتَـ / اِنْـ בתחילת פועל, ـَة, ـَات, ـُون / ـِين בסוף); מילים קטנות שמשנות את מה שבא אחריהן (מילות יחס, أَنْ, لَمْ, إِنَّ, كَانَ); ו־ال או כינוי חבור, שמונעים תנוין.",
    steps: ["קראו את כל המשפט פעם אחת ונסו להבין את הנושא — על מי ועל מה מדובר.", "מצאו את הפועל (אם יש) ואת מי שעושה את הפעולה. זה השלד של המשפט.", "לכל מילה: מצאו שורש של 3 אותיות ובדקו אילו אותיות נוספו — זה מגלה את המשקל ואת התנועות שבתוך המילה.", "שאלו מה התפקיד של המילה: נושא? מושא? אחרי מילת יחס? חלק מסמיכות? תואר של מילה אחרת?", "רק עכשיו קבעו את הסיומת לפי התפקיד (רפע / נצב / ג׳ר / ג׳זם), ובדקו אם יש ال או סמיכות (אז אין תנוין).", "קראו שוב את כל המשפט עם הניקוד שבחרתם ובדקו שהמשמעות הגיונית."],
    examples: [{ ar: "كَتَبَ الطَّالِبُ الدَّرْسَ.", he: "התלמיד כתב את השיעור — كتب בא לפני מי שכותב, ולכן זה פועל פעיל: كَتَبَ." }, { ar: "قَرَأْتُ ثَلَاثَةَ كُتُبٍ.", he: "קראתי שלושה ספרים — אחרי מספר בא שם, ולכן כאן זה كُتُبٍ (ספרים)." }, { ar: "الْكِتَابُ مُفِيدٌ.", he: "הספר מועיל — מבתדא וח׳בר, שניהם ברפע." }, { ar: "ذَهَبْتُ إِلَى الْمَكْتَبَةِ.", he: "הלכתי לספרייה — אחרי إِلَى בא ג׳ר." }],
    contrast: [{ ar: "عَلِمَ الْوَلَدُ الْخَبَرَ.", he: "הילד ידע את החדשה (בניין 1)." }, { ar: "عَلَّمَ الْمُعَلِّمُ الْوَلَدَ.", he: "המורה לימד את הילד (בניין 2 — שדה על האות האמצעית)." }],
    traps: ["להחליט על הסיומת לפני שמבינים את התפקיד של המילה.", "לקרוא כל מילה בנפרד בלי לבדוק את ההקשר.", "לשכוח שאחרי ال או בסמיכות אין תנוין."] },
  { title: "2) פועל פעיל או סביל", srs: ["nq-voice"],
    body: "פועל פעיל (مَبْنِيٌّ لِلْمَعْلُومِ) — יודעים מי עשה את הפעולה, והעושה (فَاعِل) מופיע אחרי הפועל: كَتَبَ الطَّالِبُ — התלמיד כתב.\nפועל סביל (مَبْنِيٌّ لِلْمَجْهُولِ) — לא אומרים מי עשה, והדבר שהפעולה נעשתה בו הופך לנושא (نَائِبُ الْفَاعِلِ): كُتِبَتِ الرِّسَالَةُ — המכתב נכתב.\nבכתב בלי ניקוד שתי הצורות נראות אותו דבר (كتب), ולכן ההבדל נקבע רק לפי ההקשר. בניקוד: בעבר הסביל הוא ضمة על האות הראשונה וכסרה לפני האחרונה (فُعِلَ: كُتِبَ, سُرِقَ, فُتِحَ). בעתיד: ضمة על התחילית ופתחה לפני האחרונה (يُفْعَلُ: يُكْتَبُ, يُسْرَقُ).",
    recog: "שאלו: האם המילה שאחרי הפועל יכולה לעשות את הפעולה? תלמיד יכול לכתוב — פעיל. מכתב לא יכול לכתוב — סביל.\nרמזים לסביל: אין עושה במשפט; יש مِنْ قِبَلِ (על ידי); הנושא הוא חפץ שקרה לו משהו (מכונית נגנבה, דלת נפתחה); או שהדובר אומר שלא ידוע מי עשה.",
    steps: ["מצאו את הפועל ואת המילה שבאה אחריו.", "שאלו: האם המילה הזאת עושה את הפעולה, או שהפעולה נעשית בה?", "אם היא עושה — פעיל: בעבר فَعَلَ (פתחה על האות הראשונה), בעתיד يَفْعُلُ.", "אם הפעולה נעשית בה — סביל: בעבר فُعِلَ, בעתיד يُفْعَلُ.", "בדקו התאמה: לפועל סביל אין מפעול בה, והשם שאחריו ברפע (نَائِبُ فَاعِلٍ)."],
    examples: [{ ar: "سُرِقَتْ سَيَّارَتِي أَمْسِ.", he: "המכונית שלי נגנבה אתמול (סביל)." }, { ar: "فُتِحَ الْبَابُ فَجْأَةً.", he: "הדלת נפתחה פתאום (סביל)." }, { ar: "يُدْرَسُ هٰذَا الْمَوْضُوعُ فِي الْجَامِعَةِ.", he: "הנושא הזה נלמד באוניברסיטה (סביל בעתיד)." }, { ar: "سَرَقَ اللِّصُّ السَّيَّارَةَ.", he: "הגנב גנב את המכונית (פעיל — יש עושה)." }],
    contrast: [{ ar: "كَتَبَ الْكَاتِبُ الْقِصَّةَ.", he: "הסופר כתב את הסיפור — פעיל; הסיפור מנצוב (מושא)." }, { ar: "كُتِبَتِ الْقِصَّةُ.", he: "הסיפור נכתב — סביל; הסיפור מרפוע (נאיב פאעל)." }],
    traps: ["לקרוא כל פועל בלי ניקוד כפעיל רק כי זו הקריאה הרגילה.", "לשים פתחה על השם שאחרי פועל סביל — הוא ברפע, כי הוא הנושא החדש.", "לבלבל בין كُتِبَ (נכתב) לבין كُتُب (ספרים): אם יש אחריו שם שהוא הנושא ואין פועל אחר — כנראה פועל."] },
  { title: "3) בניינים: איזה בניין מסתתר בשלד?", srs: ["nq-form"],
    body: "לפועל הערבי יש 10 בניינים (أَوْزَان), וכל בניין משנה את המשמעות של השורש. בלי ניקוד, בניין 1 ובניין 2 נכתבים אותו דבר (علم), ולכן הבחירה נעשית לפי המשמעות.\nבניין 1 فَعَلَ / فَعِلَ — המשמעות הבסיסית (عَلِمَ = ידע, دَرَسَ = למד).\nבניין 2 فَعَّلَ — שדה על האות האמצעית; בדרך כלל ״לגרום למישהו״ או פעולה מוגברת (عَلَّمَ = לימד, قَدَّمَ = הציג).\nבניין 3 فَاعَلَ — א אחרי האות הראשונה; פעולה עם מישהו (سَاعَدَ = עזר, شَارَكَ = השתתף).\nבניין 4 أَفْعَلَ — أَ בהתחלה וסכון על האות הראשונה של השורש (أَرْسَلَ = שלח).\nבניינים 5 تَفَعَّلَ ו־6 تَفَاعَلَ — تَ בהתחלה (تَعَلَّمَ = למד בעצמו, تَعَاوَنَ = שיתפו פעולה).\nבניינים 7, 8, 10 — اِنْـ, ـتَـ אחרי האות הראשונה, اِسْتَـ (اِنْكَسَرَ = נשבר, اِجْتَمَعَ = התכנס, اِسْتَخْدَمَ = השתמש).",
    recog: "בניינים 3–10 מזוהים לפי אותיות נוספות שרואים גם בלי ניקוד (ا אחרי האות הראשונה, ت בהתחלה, ان, ت אחרי האות הראשונה, است). הבעיה העיקרית היא בניין 1 מול בניין 2, כי השדה לא נכתבת. כאן מכריעה המשמעות: האם מישהו גורם למישהו אחר לעשות או לקבל משהו? אם כן — כנראה בניין 2.",
    steps: ["מצאו את 3 אותיות השורש והפרידו את האותיות הנוספות.", "אם יש אותיות נוספות — הן מגלות את הבניין (ראו הרשימה למעלה).", "אם אין — זה בניין 1 או 2. שאלו: יש מושא שהפעולה נגרמת לו (לימד אותו, הציג משהו)? אם כן ← בניין 2 עם שדה.", "בדקו שהמשמעות מתאימה לשאר המשפט."],
    examples: [{ ar: "عَلَّمَ الْأُسْتَاذُ الطُّلَّابَ الْقِرَاءَةَ.", he: "המרצה לימד את הסטודנטים קריאה (בניין 2)." }, { ar: "قَدِمَ الضُّيُوفُ مِنْ بَعِيدٍ.", he: "האורחים הגיעו מרחוק (בניין 1)." }, { ar: "قَدَّمَ الطَّالِبُ بَحْثَهُ.", he: "הסטודנט הציג את עבודת המחקר שלו (בניין 2)." }, { ar: "اِسْتَخْدَمْتُ الْحَاسُوبَ.", he: "השתמשתי במחשב (בניין 10)." }],
    contrast: [{ ar: "قَدِمَ أَخِي مِنَ السَّفَرِ.", he: "אחי חזר מהנסיעה — قَدِمَ = הגיע." }, { ar: "قَدَّمَ أَخِي هَدِيَّةً لِأُمِّي.", he: "אחי נתן מתנה לאמא — قَدَّمَ = הגיש, נתן." }],
    traps: ["לשכוח את השדה של בניין 2 כי היא לא נכתבת.", "לבלבל בין أَرْسَلَ (הוא שלח — בניין 4 בעבר) לבין أُرْسِلُ (אני שולח — עתיד): בדקו את הזמן ואת הגוף במשפט."] },
  { title: "4) اسم فاعل או اسم مفعول (העושה או מי שהפעולה נעשתה בו)", srs: ["nq-part"],
    body: "اِسْمُ الْفَاعِلِ — מי שעושה את הפעולה (בינוני פועל): كَاتِب = כותב, مُعَلِّم = מורה (מי שמלמד).\nاِسْمُ الْمَفْعُولِ — מי או מה שהפעולה נעשית בו (בינוני סביל): مَكْتُوب = כתוב, مُعَلَّم = מי שלימדו אותו.\nבבניין 1 הצורות שונות ונראות גם בלי ניקוד: فَاعِل (كَاتِب) מול مَفْعُول (مَكْتُوب).\nבבניינים 2–10 שתי הצורות מתחילות ב־مُـ ונכתבות אותו דבר בלי ניקוד! ההבדל היחיד הוא התנועה לפני האות האחרונה: כסרה = העושה (مُرْسِل = השולח), פתחה = מה שנעשה (مُرْسَل = הנשלח).",
    recog: "כשרואים מילה שמתחילה ב־م ויש בה אותיות נוספות מעבר לשורש — חשבו על اسم فاعل או اسم مفعول של בניין נגזר. שאלו: המילה מתארת את מי שעושה, או את מי שהפעולה נעשית בו? מכתב נשלח (مُرْسَل), אדם שולח (مُرْسِل). מכונית משומשת (مُسْتَعْمَلَة), אדם משתמש (مُسْتَعْمِل).",
    steps: ["זהו את המשקל: האם המילה מתחילה ב־مُـ? איזה בניין זה (שדה? ت? است?)", "שאלו: המילה מתארת עושה, או דבר שהפעולה נעשית בו?", "עושה ← כסרה לפני האות האחרונה (مُفَعِّل, مُسْتَفْعِل). נעשה בו ← פתחה (مُفَعَّل, مُسْتَفْعَل).", "בדקו את המשמעות במשפט: ההיגיון מכריע."],
    examples: [{ ar: "الْمُعَلِّمُ يَشْرَحُ الدَّرْسَ.", he: "המורה מסביר את השיעור (اسم فاعل)." }, { ar: "وَصَلَتِ الرِّسَالَةُ الْمُرْسَلَةُ.", he: "המכתב שנשלח הגיע (اسم مفعول)." }, { ar: "اِشْتَرَيْتُ سَيَّارَةً مُسْتَعْمَلَةً.", he: "קניתי מכונית משומשת (اسم مفعول)." }, { ar: "فَرِحَ الْمُشَاهِدُونَ بِالْمُبَارَاةِ.", he: "הצופים שמחו במשחק (اسم فاعل)." }],
    contrast: [{ ar: "كَتَبَ الْمُرْسِلُ اسْمَهُ عَلَى الظَّرْفِ.", he: "השולח כתב את שמו על המעטפה — מי ששולח: כסרה." }, { ar: "وَصَلَ الطَّرْدُ الْمُرْسَلُ.", he: "החבילה שנשלחה הגיעה — מה שנשלח: פתחה." }],
    traps: ["לקרוא כל مُـ כ־اسم فاعل מתוך הרגל.", "לשכוח שבבניין 1 اسم المفعول הוא مَفْعُول (مَكْتُوب) ולא מתחיל ב־مُـ.", "בפעלים חלולים בבניינים 8 ו־10 (مُخْتَار, مُحْتَاج) שתי הצורות זהות גם בניקוד — שם רק ההקשר מכריע."] },
  { title: "5) מצדרים (שם הפעולה) לפי בניין", srs: ["nq-masdar"],
    body: "مَصْدَر הוא שם הפעולה (כמו ״כתיבה״, ״לימוד״, ״עזרה״). לכל בניין נגזר יש משקל קבוע של מצדר, ולכן אם יודעים את הבניין — יודעים איך לקרוא את המצדר גם בלי ניקוד:\nבניין 2: تَفْعِيل (تَعْلِيم, تَدْرِيس).\nבניין 3: مُفَاعَلَة (مُسَاعَدَة, مُشَارَكَة).\nבניין 4: إِفْعَال (إِرْسَال, إِعْلَان) — כסרה מתחת לאלף!\nבניין 5: تَفَعُّل (تَعَلُّم) — ضمة לפני האות האחרונה. בניין 6: تَفَاعُل (تَعَاوُن).\nבניין 7: اِنْفِعَال (اِنْكِسَار). בניין 8: اِفْتِعَال (اِجْتِمَاع). בניין 10: اِسْتِفْعَال (اِسْتِخْدَام).\nבבניין 1 המצדר לא קבוע (دَرْس, كِتَابَة, ذَهَاب) — צריך להכיר אותו מהמילון.",
    recog: "מצדר הוא שם, ולכן הוא בא במקומות של שם: אחרי מילת יחס, עם ال, כמושא או כנסמך. כשרואים مـ ואחריה ا (مساعدة), ت בהתחלה ו־ي לפני האות האחרונה (تعليم), או است ואחריה ا (استخدام) — זה כמעט תמיד מצדר ולא פועל.",
    steps: ["זהו שהמילה היא שם (עם ال, אחרי מילת יחס, בסמיכות) ולא פועל.", "זהו את הבניין לפי האותיות הנוספות.", "הלבישו את משקל המצדר של הבניין (تَفْعِيل, مُفَاعَلَة, إِفْعَال ...).", "הוסיפו סיומת לפי התפקיד במשפט."],
    examples: [{ ar: "التَّعْلِيمُ مُهِمٌّ لِكُلِّ طِفْلٍ.", he: "החינוך חשוב לכל ילד (בניין 2)." }, { ar: "شَكَرْتُهُ عَلَى الْمُسَاعَدَةِ.", he: "הודיתי לו על העזרה (בניין 3)." }, { ar: "تَمَّ إِرْسَالُ الطَّلَبِ.", he: "שליחת הבקשה הושלמה (בניין 4)." }, { ar: "الِاجْتِمَاعُ فِي السَّاعَةِ الْعَاشِرَةِ.", he: "הישיבה בשעה עשר (בניין 8)." }],
    contrast: [{ ar: "إِعْلَانٌ", he: "הודעה, פרסום — מצדר של בניין 4: כסרה מתחת לאלף." }, { ar: "أَعْلَنَ", he: "הודיע — פועל עבר של בניין 4: פתחה על האלף." }],
    traps: ["לקרוא إِفْعَال עם פתחה (أَفْعَال) — זה משקל של רבים שבורים: أَعْلَام = דגלים, אבל إِعْلَام = תקשורת.", "לקרוא تَفَعُّل עם כסרה (تَعَلِّم ✗) — במצדר של בניין 5 יש ضمة: تَعَلُّم."] },
  { title: "6) רבים שבורים: לזהות את המשקל", srs: ["nq-plural"],
    body: "רבים שבורים (جَمْعُ التَّكْسِيرِ) נוצרים משינוי התנועות והאותיות בתוך המילה, ולא מהוספת סיומת. כדאי להכיר את המשקלים הנפוצים, כי בלי ניקוד הם נראים כמו מילים אחרות:\nفُعُول: دُرُوس, بُيُوت. أَفْعَال: أَقْلَام, أَوْلَاد. فُعُل: كُتُب, طُرُق, مُدُن. فِعَال: رِجَال, جِبَال.\nفُعَلَاء: وُزَرَاء, عُلَمَاء. فَوَاعِل / مَفَاعِل / مَفَاعِيل: شَوَارِع, مَدَارِس, مَفَاتِيح — שלושת האחרונים ו־فُعَلَاء הם ממנוע מן הצרף.",
    recog: "רמזים לרבים: מספר לפני המילה (ثَلَاثَة), תואר בנקבה יחידה שבא אחרי רבים של לא־אדם (كُتُب كَثِيرَة), פועל בנקבה לפני רבים של לא־אדם, או כינוי ـهَا שמתייחס אליה. אם יש א אחרי האות השנייה ושתי אותיות אחריה (شوارع, مدارس) — זה כמעט בטוח משקל مَفَاعِل / فَوَاعِل.",
    steps: ["שאלו אם ההקשר מדבר על אחד או על הרבה (מספר, ״כמה״, ״כל״, תואר).", "אם רבים ואין סיומת ـون / ـات — חפשו משקל של רבים שבורים.", "התאימו את התנועות למשקל (فُعُل = ضمة ואז ضمة, أَفْعَال = פתחה, סכון, פתחה).", "זכרו: משקלי مَفَاعِل ו־فُعَلَاء הם ממנוע מן הצרף — בלי תנוין."],
    examples: [{ ar: "فِي الْمَدِينَةِ شَوَارِعُ وَاسِعَةٌ.", he: "בעיר יש רחובות רחבים (فَوَاعِل)." }, { ar: "قَرَأْتُ كُتُبًا كَثِيرَةً.", he: "קראתי ספרים רבים (فُعُل)." }, { ar: "اِجْتَمَعَ الْوُزَرَاءُ أَمْسِ.", he: "השרים התכנסו אתמול (فُعَلَاء)." }, { ar: "لِلْبَيْتِ أَبْوَابٌ كَبِيرَةٌ.", he: "לבית יש דלתות גדולות (أَفْعَال)." }],
    contrast: [{ ar: "كَتَبَ", he: "כתב — פועל (אין מספר לפניו, יש עושה אחריו)." }, { ar: "كُتُب", he: "ספרים — רבים שבורים (בא אחרי מספר או לפני תואר)." }],
    traps: ["להוסיף תנוין לרבים במשקל مَفَاعِل / فُعَلَاء (مَدَارِسٌ ✗ ← مَدَارِسُ ✓).", "לחשוב שתואר בנקבה (كَثِيرَة) מעיד שהשם נקבה — לרבים של לא־אדם התואר תמיד בנקבה יחידה."] },
  { title: "7) מילים דו־משמעיות: ההקשר מכריע", srs: ["nq-context"],
    body: "הרבה מילים בלי ניקוד יכולות להיקרא בשתיים או שלוש דרכים, כל אחת עם משמעות אחרת. דוגמאות מוכרות:\nعلم: عِلْم (מדע, ידע), عَلَم (דגל), عَلِمَ (ידע), عَلَّمَ (לימד).\nذهب: ذَهَب (זהב), ذَهَبَ (הלך).\nقصر: قَصْر (ארמון), قِصَر (קוצר), قَصُرَ (התקצר).\nملك: مَلِك (מלך), مَلَكَ (היה הבעלים של), مُلْك (שלטון, רכוש).\nحمل: حَمَلَ (נשא), حَمْل (נשיאה, היריון).",
    recog: "שאלו שתי שאלות: (1) איזה סוג מילה נדרש כאן — פועל או שם? אם כבר יש פועל במשפט, ויש ال או מילת יחס לפני המילה — זה שם. (2) איזו משמעות מתאימה לשאר המשפט? טבעת עשויה מזהב (ذَهَب), לא מ״הלך״.",
    steps: ["רשמו לעצמכם את כל הקריאות האפשריות של השלד.", "בדקו מה לפני המילה: ال, מילת יחס או מספר ← שם; אם אחריה בא מי שעושה ← פועל.", "בחרו את המשמעות שמתאימה להקשר.", "בדקו שהסיומת מתאימה לתפקיד."],
    examples: [{ ar: "الْعِلْمُ نُورٌ.", he: "הידע הוא אור — עם ال: שם." }, { ar: "رُفِعَ الْعَلَمُ فَوْقَ الْمَدْرَسَةِ.", he: "הדגל הונף מעל בית הספר." }, { ar: "اِشْتَرَتْ خَاتَمًا مِنْ ذَهَبٍ.", he: "היא קנתה טבעת מזהב." }, { ar: "ذَهَبَ الْوَلَدُ إِلَى الْبَيْتِ.", he: "הילד הלך הביתה." }],
    contrast: [{ ar: "زَارَ الْمَلِكُ الْمَدِينَةَ.", he: "המלך ביקר בעיר." }, { ar: "مَلَكَ أَبِي أَرْضًا وَاسِعَةً.", he: "אבא שלי היה הבעלים של אדמה רחבה." }],
    traps: ["לבחור במשמעות הנפוצה ביותר בלי לבדוק את ההקשר.", "לשכוח שאותו שלד יכול להיות פועל וגם שם — מה שלפניו ואחריו מכריע."] },
];
