    examples: [{ ar: "دَخَلَ الْمَرِيضُ مُسْتَشْفًى كَبِيرًا.", he: "החולה נכנס לבית חולים גדול (מקצור; התואר מראה את הנצב)." }, { ar: "حَكَمَ الْقَاضِي بِالْعَدْلِ.", he: "השופט שפט בצדק (מנקוץ ברפע)." }, { ar: "سَأَلْتُ الْمُحَامِيَ سُؤَالًا.", he: "שאלתי את עורך הדין שאלה (מנקוץ בנצב — פתחה גלויה)." }, { ar: "هٰذَا نَادٍ رِيَاضِيٌّ.", he: "זה מועדון ספורט (מנקוץ ברפע בלי ال)." }],
