  reminder: ["II تَفْعِيل · III مُفَاعَلَة / فِعَال · IV إِفْعَال · V تَفَعُّل · VI تَفَاعُل · VII اِنْفِعَال · VIII اِفْتِعَال · X اِسْتِفْعَال. בבניין I אין משקל קבוע — לומדים בעל פה. בחלולים: IV ו־ X מאבדים את אות האמצע ומקבלים ة (إِقَامَة, اِسْتِقَالَة), וב־ VII ו־ VIII האמצע הופכת ל־ي (اِخْتِيَار)."],
  reminderBlocks: [
    { title: "1) מצדר של בניין I", body: "אין כלל קבוע, וצריך ללמוד כל מצדר עם הפועל. משקלים נפוצים: فَعْل (فَهْم), فُعُول (دُخُول), فِعَالَة (كِتَابَة), فَعَال (ذَهَاب). בחלולים: قَالَ ← قَوْل, نَامَ ← نَوْم, زَارَ ← زِيَارَة, عَادَ ← عَوْدَة.", examples: [{ ar: "الْكِتَابَةُ مُمْتِعَةٌ.", he: "הכתיבה מהנה." }, { ar: "زِيَارَةُ الْمَتْحَفِ", he: "הביקור במוזיאון" }], pitfall: "לפועל אחד בבניין I יכולים להיות כמה מצדרים במשמעויות שונות (دَرْس שיעור / دِرَاسَة לימודים)." },
    { title: "2) מצדרי הבניינים II–X", body: "כאן המשקל קבוע: II دَرَّسَ ← تَدْرِيس; III سَاعَدَ ← مُسَاعَدَة (ולעיתים فِعَال: قِتَال); IV أَرْسَلَ ← إِرْسَال; V تَعَلَّمَ ← تَعَلُّم; VI تَعَاوَنَ ← تَعَاوُن; VII اِنْقَطَعَ ← اِنْقِطَاع; VIII اِجْتَمَعَ ← اِجْتِمَاع; X اِسْتَخْدَمَ ← اِسْتِخْدَام.", examples: [{ ar: "تَعَلُّمُ اللُّغَاتِ مُفِيدٌ.", he: "לימוד שפות מועיל." }, { ar: "حَضَرْتُ الِاجْتِمَاعَ.", he: "השתתפתי בישיבה." }], pitfall: "במצדרי VII, VIII ו־ X יש כסרה אחרי הפעם השנייה של העיצור (اِجْتِـ, اِسْتِـ) ואלף לפני האות האחרונה." },
    { title: "3) מצדרים של חלולים (أجوف)", body: "IV: أَقَامَ ← إِقَامَة, أَدَارَ ← إِدَارَة (אות האמצע נעלמת ונוספת ة). X: اِسْتَقَالَ ← اِسْتِقَالَة, اِسْتَطَاعَ ← اِسْتِطَاعَة. VII ו־ VIII: האמצע הופכת ל־ي — اِخْتَارَ ← اِخْتِيَار, اِشْتَاقَ ← اِشْتِيَاق, اِنْقَادَ ← اِنْقِيَاد.", examples: [{ ar: "كَانَتِ الْإِقَامَةُ مُرِيحَةً.", he: "השהייה הייתה נוחה." }, { ar: "الِاخْتِيَارُ صَعْبٌ.", he: "הבחירה קשה." }], pitfall: "إِقْوَام ו־ اِخْتِوَار — שגוי: הוו של השורש לא מופיעה." },
    { title: "4) שימוש במצדר", body: "המצדר הוא שם עצם לכל דבר: נושא, מושא, סמיכות. המושא של הפועל נעשה مضاف إليه: تَعَلُّمُ اللُّغَةِ. במקום أَنْ + מצארע אפשר מצדר: أُرِيدُ أَنْ أَتَعَلَّمَ = أُرِيدُ التَّعَلُّمَ.", examples: [{ ar: "قَرَّرْتُ الِاشْتِرَاكَ فِي النَّادِي.", he: "החלטתי להירשם למועדון." }, { ar: "اِسْتِخْدَامُ الْهَاتِفِ مَمْنُوعٌ.", he: "השימוש בטלפון אסור." }], pitfall: "המצדר מקבל יחסה לפי תפקידו במשפט: כמושא — פתחה." },
  ],
